# Kaggle driver: B-form Case II census (cnt9c.py) on top of the repo pipeline research/nine-term-outside-colspace
# (CrocSwap main 463113d67), code embedded as a tar.gz.  Prints everything; all logs also written to /kaggle/working.
import os, sys, time, subprocess, base64, io, tarfile, threading
print('START driver', time.strftime('%H:%M:%S'), flush=True)
W = '/kaggle/working'; os.chdir(W)
tarfile.open(fileobj=io.BytesIO(base64.b64decode(''))).extractall(W)
os.makedirs('run', exist_ok=True)
T0 = time.time(); state = {'step': 'init'}
def hb():
    while True:
        time.sleep(45); print('HEARTBEAT driver', round(time.time() - T0), 's, step', state['step'], flush=True)
threading.Thread(target=hb, daemon=True).start()
steps = [('aut104', ['aut104.py']), ('cliques', ['cliques.py', 'P104']), ('pairs', ['pairs_fast.py', 'P104']),
         ('mkcnt', ['mk_cnt_pkl.py', 'P104']), ('cnt9b', ['cnt9b.py', 'P104'])] +         [('cnt9c_' + V, ['cnt9c.py', 'P104', V]) for V in ('V0', 'V1', 'V2', 'V3')]
rc = 0
for name, cmd in steps:
    state['step'] = name; t = time.time(); print('== STEP', name, cmd, flush=True)
    p = subprocess.Popen([sys.executable, '-u', '-B', os.path.join(W, 'checks', cmd[0])] + cmd[1:], cwd=os.path.join(W, 'run'),
                         stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    lg = open(os.path.join(W, name + '.log'), 'w'); n = 0
    for line in p.stdout:
        lg.write(line); lg.flush(); n += 1
        if not line.startswith('CAND') or n < 200 or 'ALIVE' in line: print(line, end='', flush=True)
    r = p.wait(); print('EXIT', name, r, round(time.time() - t), 's', flush=True); rc = rc or r
    if r and name in ('aut104', 'cliques', 'pairs', 'mkcnt'): break
import shutil; shutil.rmtree(os.path.join(W, 'checks'), ignore_errors=True); shutil.rmtree(os.path.join(W, 'data'), ignore_errors=True)
print('DONE driver rc', rc, flush=True)
if rc: raise SystemExit(rc)
